"""Minimal shim for objectmaphelper used by InterOps object maps.

Provides `Wildcard` and `Contains` helpers as simple wrappers.
"""
from typing import Any


class WildcardClass:
    def __init__(self, pattern: str):
        self.pattern = pattern

    def __repr__(self):
        return f"Wildcard({self.pattern!r})"


def Wildcard(pattern: str) -> Any:
    return WildcardClass(pattern)


def Contains(sub: str) -> Any:
    return lambda s: sub in s
